export type DrawName = keyof typeof MARKS;

/**
 * `size` is the rendered width. A number is px; a string is any CSS
 * length, so the hero's mark can be given a `clamp()` and track the
 * headline it sits over instead of being pinned while the type around it
 * scales. The px path keeps computing height arithmetically rather than
 * switching everything to `aspect-ratio`, because every other mark on the
 * page is already laid out against those numbers.
 *
 * Strokes are non-scaling either way, so one `--draw-w` is the same
 * visual weight on a 30px logistics mark and a 160px track drawing —
 * which is what keeps them one hand rather than one shape at several
 * weights.
 */
export function Draw({
  name,
  size,
  className = "",
}: {
  name: DrawName;
  size: number | string;
  className?: string;
}) {
  const m: Mark = MARKS[name];
  const [, , w, h] = m.box.split(" ").map(Number);
  return (
    <div
      data-heat="draw"
      aria-hidden
      className={`draw ${className}`}
      style={
        typeof size === "number"
          ? { width: size, height: (size * h) / w }
          : { width: size, aspectRatio: `${w} / ${h}` }
      }
    >
      <svg viewBox={m.box}>
        {m.d.map((d) => (
          <path key={d} d={d} />
        ))}
        {m.dashed?.map((d) => (
          <path key={d} d={d} strokeDasharray="3 4.5" />
        ))}
      </svg>
    </div>
  );
}
